"const https = require('https');
https.get('https://www.rezi.ai/', (res) => {
  let data = '';
  res.on('data', c => data += c);
  res.on('end', () => {
    const start = data.indexOf('templates_featured_wrap');
    const end = data.indexOf('Find inspiration with great resume examples');
    const slice = data.slice(start, end);

    // find all slides
    const slideRegex = /class="templates_slider_slide[^"]*"[\s\S]*?(?=(class="templates_slider_slide)|(templates_featured_content)|$)/g;

    // Let's find images, headings, and descriptions
    const slides = slice.split('class="templates_slider_slide');
    for (let i = 1; i < slides.length; i++) {
      const s = slides[i];
      const imgMatch = s.match(/<img[^>]+src="([^"]+)"[^>]*alt="([^"]+)"/);
      const h3Match = s.match(/<h3[^>]*>([^<]+)<\/h3>/);
      const pMatch = s.match(/<p>([^<]+)<\/p>/);
      console.log('SLIDE', i, {
        name: h3Match ? h3Match[1] : null,
        img: imgMatch ? imgMatch[1] : null,
        desc: pMatch ? pMatch[1] : null
      });
    }
  });
});
"

