"const https = require('https');
const fs = require('fs');

https.get('https://www.rezi.ai/', (res) => {
  let data = '';
  res.on('data', c => data += c);
  res.on('end', () => {
    const start = data.indexOf('templates_slider_panels');
    const end = data.indexOf('Find inspiration with great resume examples');
    const slice = data.slice(start, end);
    const panels = slice.split('class="templates_slider_panel swiper');
    const categories = ['Most Popular', 'Simple', 'Modern', 'Creative', 'Compact'];
    const result = {};
    for (let p = 1; p < panels.length; p++) {
      const cat = categories[p - 1];
      result[cat] = [];
      const slides = panels[p].split('class="templates_slider_slide');
      for (let s = 1; s < slides.length; s++) {
        const slide = slides[s];
        const nameMatch = slide.match(/<h3[^>]*>([^<]+)<\/h3>/);
        const imgMatch = slide.match(/<img[^>]+src="([^"]+)"/);
        const pMatch = slide.match(/<p class="[^"]*u-text-style-small[^"]*">([^<]+)<\/p>/);
        result[cat].push({
          name: nameMatch ? nameMatch[1].replace(/&#x27;/g, "'") : '',
          img: imgMatch ? imgMatch[1] : '',
          desc: pMatch ? pMatch[1].replace(/&#x27;/g, "'") : ''
        });
      }
    }
    fs.writeFileSync('rezi_templates_data.json', JSON.stringify(result, null, 2));
    console.log('Saved rezi_templates_data.json');
  });
});
"

